import type { PlayerCosmetics } from './types';

export type BallFinish = 'solid' | 'marble' | 'metal' | 'neon' | 'galaxy' | 'lava' | 'ice';

export interface BallStyle {
  id: string;
  name: string;
  finish: BallFinish;
  color: string;
  emissive?: string;
  unlockLevel: number;
}

export const DEFAULT_BALL_ID = 'classic-white';

export const BALL_STYLES: readonly BallStyle[] = [
  { id: 'classic-white', name: 'Classic White', finish: 'solid', color: '#ffffff', unlockLevel: 1 },
  { id: 'crimson', name: 'Crimson', finish: 'solid', color: '#e6492d', unlockLevel: 1 },
  { id: 'azure', name: 'Azure', finish: 'solid', color: '#2f7ff0', unlockLevel: 1 },
  { id: 'sunbeam', name: 'Sunbeam', finish: 'solid', color: '#f5c542', unlockLevel: 1 },
  { id: 'fairway', name: 'Fairway', finish: 'solid', color: '#3ec46d', unlockLevel: 1 },
  { id: 'midnight', name: 'Midnight', finish: 'solid', color: '#1b1d24', unlockLevel: 1 },
  { id: 'amethyst', name: 'Amethyst', finish: 'solid', color: '#9b5de5', unlockLevel: 1 },
  { id: 'tangerine', name: 'Tangerine', finish: 'solid', color: '#ff8c3a', unlockLevel: 1 },
  { id: 'marble-swirl', name: 'Marble Swirl', finish: 'marble', color: '#f2efe6', unlockLevel: 5 },
  { id: 'chrome-core', name: 'Chrome Core', finish: 'metal', color: '#b9c2cc', unlockLevel: 8 },
  { id: 'neon-pulse', name: 'Neon Pulse', finish: 'neon', color: '#19f0d8', emissive: '#00b8a3', unlockLevel: 12 },
  { id: 'galaxy-drift', name: 'Galaxy Drift', finish: 'galaxy', color: '#2b1e5c', emissive: '#6d4bd6', unlockLevel: 18 },
  { id: 'lava-core', name: 'Lava Core', finish: 'lava', color: '#7a1c0b', emissive: '#ff5a1f', unlockLevel: 24 },
  { id: 'glacier-ice', name: 'Glacier Ice', finish: 'ice', color: '#bfe9ff', unlockLevel: 30 },
];

export function ballStyleById(id: string): BallStyle | undefined {
  return BALL_STYLES.find((style) => style.id === id);
}

export function unlockedBallStyles(level: number): readonly BallStyle[] {
  return BALL_STYLES.filter((style) => style.unlockLevel <= level);
}

export function syncUnlockedCosmetics(cosmetics: PlayerCosmetics, level: number): PlayerCosmetics {
  const owned = new Set(cosmetics.unlockedBallIds);
  unlockedBallStyles(level).forEach((style) => owned.add(style.id));
  const catalogIds = BALL_STYLES.filter((style) => owned.has(style.id)).map((style) => style.id);
  const customIds = cosmetics.unlockedBallIds.filter(
    (id, index) => !ballStyleById(id) && cosmetics.unlockedBallIds.indexOf(id) === index,
  );
  const unlockedBallIds = [...catalogIds, ...customIds];
  return {
    ...cosmetics,
    ballId: unlockedBallIds.includes(cosmetics.ballId) ? cosmetics.ballId : DEFAULT_BALL_ID,
    unlockedBallIds,
    unlockedTrailIds: [...cosmetics.unlockedTrailIds],
    unlockedHatIds: [...cosmetics.unlockedHatIds],
  };
}
