import { describe, expect, it } from 'vitest';
import { BALL_STYLES, ballStyleById, syncUnlockedCosmetics, unlockedBallStyles } from './cosmetics';
import { defaultCosmetics } from './profile';

const allIds = BALL_STYLES.map((style) => style.id);

describe('ball cosmetics catalog', () => {
  it('exposes unique ids that resolve through ballStyleById', () => {
    expect(new Set(allIds).size).toBe(BALL_STYLES.length);
    BALL_STYLES.forEach((style) => expect(ballStyleById(style.id)).toBe(style));
    expect(ballStyleById('not-a-ball')).toBeUndefined();
  });

  it('unlocks exactly the eight solid colours at level 1', () => {
    const styles = unlockedBallStyles(1);
    expect(styles).toHaveLength(8);
    expect(styles.every((style) => style.finish === 'solid')).toBe(true);
    expect(styles.map((style) => style.id)).toContain('classic-white');
  });

  it('unlocks the whole catalog at level 30 and keeps emissive finishes glowing', () => {
    expect(unlockedBallStyles(30)).toHaveLength(BALL_STYLES.length);
    expect(unlockedBallStyles(29)).toHaveLength(BALL_STYLES.length - 1);
    const glowing = BALL_STYLES.filter((style) => style.emissive);
    expect(glowing.map((style) => style.finish)).toEqual(['neon', 'galaxy', 'lava']);
  });

  it('falls back to classic-white while the selected ball is still locked', () => {
    const cosmetics = { ...defaultCosmetics(), ballId: 'glacier-ice' };
    expect(syncUnlockedCosmetics(cosmetics, 12).ballId).toBe('classic-white');
    expect(syncUnlockedCosmetics(cosmetics, 30).ballId).toBe('glacier-ice');
  });

  it('merges owned ids with level rewards in catalog order without duplicates', () => {
    const cosmetics = {
      ...defaultCosmetics(),
      ballId: 'lava-core',
      unlockedBallIds: ['lava-core', 'classic-white', 'classic-white', 'event-pumpkin'],
    };
    const next = syncUnlockedCosmetics(cosmetics, 5);
    expect(next.unlockedBallIds).toEqual([...allIds.slice(0, 9), 'lava-core', 'event-pumpkin']);
    expect(next.ballId).toBe('lava-core');
  });

  it('never mutates the cosmetics passed in', () => {
    const cosmetics = defaultCosmetics();
    const snapshot = JSON.parse(JSON.stringify(cosmetics));
    const next = syncUnlockedCosmetics(cosmetics, 30);
    expect(cosmetics).toEqual(snapshot);
    expect(next).not.toBe(cosmetics);
    expect(next.unlockedBallIds).not.toBe(cosmetics.unlockedBallIds);
    expect(next.unlockedTrailIds).not.toBe(cosmetics.unlockedTrailIds);
    expect(next.unlockedBallIds).toEqual(allIds);
  });
});
